import type { LocationSeed } from "./seed";

export const locations = [
  { id: "winterfell", name: "Winterfell", region: "The North", background: "winterfell", summary: "House Stark's ancestral castle in the North, warmed by natural hot springs.", description: "The thousand-year seat of House Stark and effective capital of the North, a sprawling grey granite complex built over natural hot springs that pipe warmth through its walls, with a broken tower, a crypt of stone kings, and a three-acre godswood centred on a weirwood over a black pool. It is ruled by the Starks, then by the Boltons after the sack, then by the Starks again; its Great Hall seats five hundred beneath the direwolf banners. This is where Ned is Lord, where Bran falls from the tower, where the Boltons flay their way through the Winterfell they stole, and where the Battle of the Bastards and the Long Night are fought.", also_called: [], adjacent: ["winterfell-great-hall","winterfell-godswood","the-kingsroad","white-harbor","the-dreadfort","deepwood-motte"] },
  { id: "winterfell-great-hall", name: "Winterfell's Great Hall", region: "The North", background: "winterfell-great-hall", summary: "Winterfell's feast hall under the direwolf banners, where the North's lords are gathered.", description: "The long stone hall at the heart of Winterfell, benched for five hundred with a raised dais for the high table, hearths burning at both ends and the banners of the northern houses hanging in the smoke. It is where Winterfell does its business in public: Robert's welcoming feast, at which Jon is seated at the far end with the bastards and the boys and drinks himself out of the evening; the naming of Robb as King in the North, with the Greatjon's sword out and every lord on his feet; and in the show the hall where Lyanna Mormont shames grown men into declaring for Jon. Under the Boltons its tables feed a house nobody wants to eat beside, and after the Long Night it is where the survivors count themselves and drink to the dead.", also_called: ["the great hall"], adjacent: ["winterfell","winterfell-godswood"], within: "winterfell" },
  { id: "winterfell-godswood", name: "Winterfell's Godswood", region: "The North", background: "winterfell-godswood", summary: "Winterfell's three-acre weirwood grove around a black pool, where the old gods are kept.", description: "Three acres of old forest inside the castle walls that no axe has ever touched, dark and cold and quiet even in summer, with a weirwood at its centre whose carved red face weeps sap above a pool of black water warmed from below by the hot springs. It is the oldest thing in Winterfell and one of the last places in the North where the old gods are kept the way the First Men kept them, without septs, septons or words. Ned comes here to clean Ice and to say the things he will not say indoors; Catelyn, who prays to the Seven, comes anyway; Bran finds the three-eyed crow waiting for him here; and Theon dies in front of the heart tree with a knife in his hand.", also_called: ["the godswood","the heart tree"], adjacent: ["winterfell","winterfell-great-hall"], within: "winterfell" },
  { id: "castle-black", name: "Castle Black", region: "The Wall", background: "castle-black", summary: "Night's Watch headquarters on the Wall's southern base, timber keeps and ice tunnels.", description: "The Night's Watch's main stronghold and the seat of its Lord Commander, one of only three of the Wall's nineteen castles still garrisoned; it is not truly a castle at all, having no walls to east, west or south, just timber keeps and stone towers huddled against the ice with wormway tunnels beneath for winter. Black brothers, poachers and exiled lordlings live here under vows, fed on salt beef and resentment, with Mole's Town half a league down the kingsroad for whoring. This is where Jon Snow takes the black, where Maester Aemon keeps the rookery, where the wildlings assault the gate, and where Jon is stabbed by his own brothers.", also_called: ["the black castle","the Watch's castle"], adjacent: ["castle-black-training-yard","top-of-the-wall","the-gift-and-moles-town","haunted-forest","eastwatch-by-the-sea"] },
  { id: "castle-black-training-yard", name: "The Training Yard at Castle Black", region: "The Wall", background: "castle-black-training-yard", summary: "Castle Black's gravel yard where the Watch's raw recruits are drilled with blunted steel.", description: "The gravel yard under the Wall's shadow where the Night's Watch makes soldiers out of whatever the realm sends it: a rack of blunted practice swords, a row of straw-and-sand pells, and the master-at-arms shouting over the clatter while the ice throws the noise back. Ser Alliser Thorne runs it as a cruelty rather than a school, naming each boy for what he thinks of him and setting three of them on one at a time, and it is here that Jon learns a boy taught by Ser Rodrik Cassel is not brave, only better fed, and stops enjoying winning. Later Jon drills the same recruits himself, Grenn and Pyp and Sam among them, and the yard is where the garrison forms up when the horn sounds three times.", also_called: ["the training yard","the practice yard"], adjacent: ["castle-black","top-of-the-wall"], within: "castle-black" },
  { id: "top-of-the-wall", name: "Top of the Wall", region: "The Wall", background: "top-of-the-wall", summary: "The summit of the great ice Wall, wind-scoured and seven hundred feet up.", description: "The summit of a barrier of ice a hundred leagues (three hundred miles) long and over seven hundred feet high, one of the Nine Wonders Made by Man, broad enough at the crown for a dozen mounted knights to ride abreast. Up here there is only wind, sentries, the winch cage, and a view over the green sea of the haunted forest to the north and the Gift to the south; the Wall weeps meltwater in summer and kills the careless in winter. This is where Jon and Ygritte climb over the lip, where Tyrion pisses off the edge of the world, and where the Watch drops barrels of stone on the giants below.", also_called: ["atop the Wall","the Wall's summit"], adjacent: ["castle-black","castle-black-training-yard","eastwatch-by-the-sea","haunted-forest"] },
  { id: "haunted-forest", name: "The Haunted Forest", region: "Beyond the Wall", background: "haunted-forest", summary: "Vast wilderness north of the Wall, free folk villages, no roads, wights roam.", description: "A vast taiga of sentinel, soldier pine, ironwood and the only large surviving stands of weirwood, running from the Wall north to the Land of Always Winter and bounded by the Frostfangs to the west and the Shivering Sea to the east. There are no roads, only ranger roads (game trails and dry streambeds), no bridges or ferries over its lakes and rivers, and the free folk who live here in scattered villages such as Whitetree owe nothing to any king. It is where rangers vanish, where Waymar Royce meets the Others in the very first chapter, and where the dead do not stay dead.", also_called: [], adjacent: ["crasters-keep","fist-of-the-first-men","cave-of-the-three-eyed-raven","castle-black"] },
  { id: "fist-of-the-first-men", name: "Fist of the First Men", region: "Beyond the Wall", background: "fist-of-the-first-men", summary: "Ruined First Men ringfort on a bare hill beyond the Wall, Mormont's camp.", description: "A solitary steep hill beside the Milkwater that the free folk named for its look of a fist punching up through earth and wood, its bare brown slopes knuckled with stone and crowned by the chest-high ringwall of a ruined First Men ringfort. Commanding and defensible, it is where Lord Commander Mormont camps the Great Ranging, filling breaches with stakes and seeding the slopes with caltrops. Jon's direwolf Ghost digs a cache of dragonglass and a cracked warhorn from a grave below it, and the whole camp is overrun in the disaster that survivors only call the fight at the Fist.", also_called: [], adjacent: ["haunted-forest","crasters-keep","cave-of-the-three-eyed-raven"] },
  { id: "crasters-keep", name: "Craster's Keep", region: "Beyond the Wall", background: "crasters-keep", summary: "Craster's squalid wildling hall beyond the Wall, daub-and-wattle, skulls on the gate.", description: "Not a keep at all but a low windowless daub-and-wattle hall on a hill inside an earthen dike, its gate decorated with the skulls of a bear and a ram, with a midden heap, a pigsty and a sheepfold inside. Craster is a wildling who calls himself a friend to the Watch, keeps nineteen wives who are also his daughters, and gives his sons to the cold gods in the woods. Here the ranging shelters and starves, and here the mutiny at Craster's Keep kills both Craster and Lord Commander Jeor Mormont over the question of a hidden larder.", also_called: [], adjacent: ["haunted-forest","fist-of-the-first-men","castle-black"] },
  { id: "hardhome", name: "Hardhome", region: "Beyond the Wall", background: "hardhome", summary: "Burned wildling ruin on a northern bay, caves in the cliff above it.", description: "The ruins of the only town the free folk ever nearly built, on a sheltered deepwater bay at the tip of Storrold's Point beneath a great cliff pocketed with cave mouths. Six centuries ago it burned in a single night with flames so high the Watch on the Wall thought the sun was rising in the north; ash fell for half a year afterwards, and traders since have reported charred bones, corpse-choked water and screaming from the caves. In the show it is where Jon and Tormund come to evacuate thousands of wildlings, where Jon shatters a White Walker with Longclaw, and where the Night King raises the drowned dead with a lift of his arms.", also_called: [], adjacent: ["haunted-forest","eastwatch-by-the-sea","castle-black"] },
  { id: "cave-of-the-three-eyed-raven", name: "Cave of the Three-Eyed Raven", region: "Beyond the Wall", background: "cave-of-the-three-eyed-raven", summary: "Hidden cave among weirwood roots beyond the Wall, seat of the last greenseer.", description: "A cleft halfway up a wooded hillside between weirwoods, warded so that wights cannot pass, opening into a lightless cave system of weirwood roots, stalactites, stacked skulls and shafts that fall to a black river six hundred feet down. The last greenseer sits there on a throne of woven roots, half grown into the wood, attended by the last few children of the forest; the inhabitants live on mushrooms, blind white fish and goat's milk. Bran arrives here after Summer and Hodor fight off wights at the mouth, learns to see through the weirwood net, and in the show loses Hodor and Summer when the Night King breaks the wards.", also_called: ["the Three-Eyed Raven's cave","the cave beneath the weirwood"], adjacent: ["haunted-forest","fist-of-the-first-men","land-of-always-winter"] },
  { id: "land-of-always-winter", name: "The Land of Always Winter", region: "Beyond the Wall", background: "land-of-always-winter", summary: "Unmapped frozen north past the Frostfangs, legendary birthplace of the Others.", description: "The unmapped polar north past the Frostfangs where the haunted forest gives out, permanently locked in winter, frozen rivers of blue-white ice and dead plains where nothing grows. No living man has charted it; the children of the forest and the giants are said to have dwelt there in the Dawn Age, and legend holds the Others came from it during the Long Night. Bran, comatose, flies past it in vision and looks into the heart of winter and cries out, afraid.", also_called: [], adjacent: ["haunted-forest","cave-of-the-three-eyed-raven","fist-of-the-first-men"] },
  { id: "white-harbor", name: "White Harbor", region: "The North", background: "white-harbor", summary: "House Manderly's whitewashed port city, the North's only real trade harbor.", description: "The North's only city and only real trade port, seat of House Manderly at the New Castle, sitting where the White Knife empties into a firth of the Bite that has not frozen in centuries. It is clean and well ordered, whitewashed stone under steep grey slate, with more knights and more worshippers of the Seven than anywhere else north of the Neck, and a black stout prized as far as Braavos. Wyman Manderly plays the fat fool while quietly plotting for the Starks, and serves the Freys a very particular pie.", also_called: [], adjacent: ["winterfell","the-kingsroad","the-dreadfort","braavos"] },
  { id: "the-dreadfort", name: "The Dreadfort", region: "The North", background: "the-dreadfort", summary: "House Bolton's grim seat, torch brackets of flayed human hands, torture cells below.", description: "The seat of House Bolton on the north bank of the Weeping Water, a grim castle whose great hall is lit by torches held in skeletal human hands jutting from the walls, smoke-blackened rafters above and steep steps down to cold damp cells below. The Boltons were the Red Kings before they bent to the Starks and are said to keep torture chambers and a room hung with the flayed skins of their enemies, including several Kings in the North. This is Ramsay Snow's home ground, where Theon Greyjoy is unmade into Reek.", also_called: [], adjacent: ["last-hearth","karhold","winterfell","white-harbor"] },
  { id: "last-hearth", name: "Last Hearth", region: "The North", background: "last-hearth", summary: "House Umber's remote northern hall near the Wall, loud, hard-drinking giants of men.", description: "The seat of House Umber in a forest east of the kingsroad near the Gift, the northernmost major castle of the Seven Kingdoms outside the Watch's own. Its lords are enormous, loud and hard-drinking; the Greatjon loses two fingers to Robb's direwolf and then laughs about it, and in his absence the castle is run by his uncles Mors Crowfood and Hother Whoresbane. Short of men and hard against the Bay of Seals, it is the first great hall a wildling raid or an army of the dead would reach coming south.", also_called: [], adjacent: ["the-gift-and-moles-town","karhold","the-dreadfort","castle-black"] },
  { id: "bear-island", name: "Bear Island", region: "The North", background: "bear-island", summary: "House Mormont's isolated island hall in the Bay of Ice, ruled by warrior women.", description: "A remote, beautiful, bear-haunted island in the Bay of Ice north of Deepwood Motte, where House Mormont lives in a hall of huge logs behind an earthen palisade among gnarled oaks and moss-covered stone. Generations of ironborn and Frozen Shore raiders struck while the men were out fishing, so the women here learned to fight, which is why Maege and Lyanna Mormont carry themselves the way they do. Jorah Mormont forfeited it by selling poachers to a slaver, and little Lyanna later shames a hall full of grown lords into declaring for Jon Snow.", also_called: [], adjacent: ["deepwood-motte","winterfell","pyke"] },
  { id: "moat-cailin", name: "Moat Cailin", region: "The North", background: "moat-cailin", summary: "Ruined First Men towers guarding the causeway through the Neck's lizard-lion bog.", description: "An ancient First Men stronghold on the northern edge of the Neck, mostly ruin now: three moss-and-ghostskin-covered towers among basalt blocks half sunk in bog, commanding the causeway that is the only army-sized road through the swamp. Attackers must wade chest-deep past lizard-lions while all three towers shoot down on them, which is why it has kept southron armies out of the North for thousands of years. Robb's host passes it going south, and Ramsay Bolton takes it back from the ironborn by promising terms and then flaying everyone.", also_called: [], adjacent: ["winterfell","the-kingsroad","the-twins","torrhens-square"] },
  { id: "deepwood-motte", name: "Deepwood Motte", region: "The North", background: "deepwood-motte", summary: "House Glover's timber castle in the wolfswood, a longhall with one watchtower.", description: "The Glovers' seat in the wolfswood, an old timber castle: a cavernous longhall on a flat-topped hill with a fifty-foot watchtower, ringed by mossy wooden walls, ditches and a log palisade, five leagues from the Bay of Ice and three hundred miles northwest of Winterfell. It is old but not strong, which is how Asha Greyjoy takes it in a night with thirty men while the Glover brothers are away at war. Later Stannis retakes it in the snow on his doomed march toward Winterfell.", also_called: [], adjacent: ["bear-island","winterfell","torrhens-square"] },
  { id: "karhold", name: "Karhold", region: "The North", background: "karhold", summary: "House Karstark's remote riverside seat in the eastern North, defined by old grievance.", description: "The seat of House Karstark on a forested river in the eastern North south of the Bay of Seals, built by a younger son of Winterfell called Karlon Stark, so that Karl's Hold became Karhold and the Karhold Starks became the Karstarks. It is a place defined by grievance: Rickard Karstark loses two sons to Jaime Lannister in the Whispering Wood, murders two Lannister boys in revenge, and is beheaded by Robb for it, which costs Robb three hundred horse and eventually the war. With the men gone south the harvest fails and the women, children and cripples work the fields alone.", also_called: [], adjacent: ["the-dreadfort","last-hearth","eastwatch-by-the-sea"] },
  { id: "torrhens-square", name: "Torrhen's Square", region: "The North", background: "torrhens-square", summary: "House Tallhart's square lakeside keep southwest of Winterfell, stone walls, four corner towers.", description: "The Tallhart seat southwest of Winterfell on the northern shore of a large lake, a strong square keep inside thirty-foot stone walls with a square tower at each corner. Theon Greyjoy visited it with Ned Stark as a boy, and uses that knowledge to bait Ser Rodrik Cassel away from Winterfell with a false ironborn attack, stripping the castle's garrison so he can take it. A plain, unglamorous northern holdfast whose chief role in the story is to be a diversion.", also_called: [], adjacent: ["winterfell","deepwood-motte","moat-cailin"] },
  { id: "eastwatch-by-the-sea", name: "Eastwatch-by-the-Sea", region: "The Wall", background: "eastwatch-by-the-sea", summary: "Night's Watch castle on the Wall's eastern shore, galleys and mule breeding.", description: "The easternmost manned castle of the Night's Watch, on a grey windswept shore by the Bay of Seals, commanded by the brutal, blunt Cotter Pyke. It keeps galleys, some big enough to cross the narrow sea, patrols against smugglers running weapons to the free folk, and breeds the sure-footed mules that carry men up the ice. Wildlings prefer trading here to Castle Black because ships come in from overseas, and in the show it is the port the party beyond the Wall sails from to hunt a wight.", also_called: [], adjacent: ["top-of-the-wall","castle-black","hardhome","braavos"] },
  { id: "the-gift-and-moles-town", name: "The Gift and Mole's Town", region: "The Wall", background: "the-gift-and-moles-town", summary: "Watch farmland south of the Wall; Mole's Town, its half-underground brothel village.", description: "Fifty leagues of thin stony farmland south of the Wall, Brandon's Gift plus the New Gift that Queen Alysanne talked the Starks out of, given to the Night's Watch in perpetuity and now largely reclaimed by weeds and abandoned holdfasts. Its one notable settlement is Mole's Town on the kingsroad half a league from Castle Black, three-quarters of it underground in warm damp cellars and tunnels, its brothel marked above ground only by a shack with a red lantern. Black brothers go there to dig for buried treasure; Styr's raiders burn it on their way to the Wall.", also_called: ["Mole's Town","the Gift"], adjacent: ["castle-black","the-kingsroad","last-hearth"] },
  { id: "riverrun", name: "Riverrun", region: "Riverlands", background: "riverrun", summary: "House Tully's river-girt castle at the confluence of the Tumblestone and Red Fork.", description: "The Tully seat, a compact three-sided castle of red sandstone rising sheer from the water at the confluence of the Tumblestone and the Red Fork, with a man-made ditch on the third side whose sluice gates can be opened to make the whole castle an island. Properly victualled it can hold two years, which is why it is besieged rather than stormed. Here Catelyn grew up, here Hoster Tully's funeral boat drifts away while Edmure misses it with three flaming arrows, and here the Blackfish holds out alone against the Freys and the Lannisters.", also_called: [], adjacent: ["the-twins","harrenhal","inn-at-the-crossroads","lannisport","the-whispering-wood"] },
  { id: "harrenhal", name: "Harrenhal", region: "Riverlands", background: "harrenhal", summary: "The largest, cursed castle in Westeros, five colossal towers on the God's Eye.", description: "The largest castle in the Seven Kingdoms and the most cursed, built by Harren the Black on the north shore of the Gods Eye and melted on the day it was finished when Aegon the Conqueror brought Balerion down on it. Five towers of dizzying, warped size cover three times the ground of Winterfell, in rooms scaled for giants, and every house granted it has died out. Arya scrubs floors here as Weese's drudge and then as Tywin Lannister's cupbearer, Jaqen H'ghar pays three deaths, and Jaime and Brienne share a bathhouse confession.", also_called: [], adjacent: ["gods-eye-and-isle-of-faces","inn-at-the-crossroads","riverrun","the-kingsroad","the-whispering-wood","the-ruby-ford"] },
  { id: "the-twins", name: "The Twins", region: "Riverlands", background: "the-twins", summary: "House Frey's twin toll castles joined by a bridge over the Green Fork.", description: "Two identical moated stone castles facing each other across the Green Fork, joined by a bridge wide enough for two wagons and guarded at its midpoint by the Water Tower, the only crossing for hundreds of miles and squarely athwart the road from Winterfell to Riverrun. House Frey grew rich charging toll for it, and old Walder Frey has ninety-odd descendants and a very long memory. This is where 'The Rains of Castamere' strikes up, the doors bar, and the Red Wedding kills Robb Stark, Catelyn and most of three and a half thousand northmen under guest right.", also_called: [], adjacent: ["riverrun","moat-cailin","the-kingsroad","the-whispering-wood"] },
  { id: "inn-at-the-crossroads", name: "The Inn at the Crossroads", region: "Riverlands", background: "inn-at-the-crossroads", summary: "Riverlands inn where the kingsroad meets the river and high roads, chance meetings.", description: "A three-storey white-stone inn with turrets and chimneys where the kingsroad meets the river road west and the high road east to the Vale, north of the Trident near the ruby ford; it has been called the Two Crowns, the Bellringer, the Clanking Dragon and the River Inn in its time. Everyone in Westeros passes through eventually, which makes it the great engine of chance meetings: Catelyn recognises Tyrion here and has him seized in front of a full common room. In the show it is also where the Hound cuts down Polliver and Arya gets Needle back.", also_called: [], adjacent: ["the-kingsroad","harrenhal","riverrun","bloody-gate","the-ruby-ford"] },
  { id: "gods-eye-and-isle-of-faces", name: "The God's Eye and the Isle of Faces", region: "Riverlands", background: "gods-eye-and-isle-of-faces", summary: "Largest lake in Westeros; a sacred weirwood island where the First Men pacted.", description: "The largest lake in the Seven Kingdoms, blue-green in summer and the colour of cold steel in winter, with Harrenhal brooding on its northern shore and a single wooded island at its centre. On that island the children of the forest and the First Men signed the Pact that ended the Dawn Age war, and every weirwood on it was given a carved face so the gods would witness it; the order of the green men has tended them ever since. Rivermen who try to row out are turned back by sudden winds or flocks of ravens, and no Andal army ever took it.", also_called: ["the God's Eye","the Isle of Faces"], adjacent: ["harrenhal","the-kingsroad","kings-landing"] },
  { id: "the-whispering-wood", name: "The Whispering Wood", region: "Riverlands", background: "the-whispering-wood", summary: "Dense Riverlands wood near Riverrun where Robb Stark trapped and took Jaime Lannister.", description: "A thickly wooded valley where the Red Fork bends, close enough to Riverrun that horns carry and dark enough to hide an army. Robb Stark split his host at the Twins, sent two thousand men east under the Greatjon's banners as a feint, and brought the rest through these trees by night to fall on Jaime Lannister's siege camp from three sides; the fight was won in rain and darkness and cost the North some three hundred men. Jaime cut his way toward Robb through Torrhen Karstark, Eddard Karstark and Daryn Hornwood before he was pulled off his horse and taken alive, and the Whispering Wood is where the boy who rode south stopped being a boy and became the Young Wolf.", also_called: [], adjacent: ["riverrun","the-twins","harrenhal"] },
  { id: "the-ruby-ford", name: "The Ruby Ford", region: "Riverlands", background: "the-ruby-ford", summary: "Trident crossing on the kingsroad where Robert's warhammer killed Rhaegar Targaryen.", description: "The shallow crossing where the kingsroad fords the Trident, named for the day Robert Baratheon caved in Rhaegar Targaryen's breastplate with a warhammer and sent the rubies from his armour scattering into the current, ending three centuries of Targaryen rule in water that ran red a mile downstream. Smallfolk still wade the shallows in summer hoping to turn up a stone. Every army moving between the north and the capital has to cross here, and on the ride south it is beside this water that Arya and Joffrey quarrel, Nymeria takes the prince's arm, Mycah runs and the Hound rides him down — the first blood of a war fought over nothing anyone there understood.", also_called: ["the Trident"], adjacent: ["inn-at-the-crossroads","harrenhal","the-kingsroad"] },
  { id: "the-kingsroad", name: "The Kingsroad", region: "The Roads", background: "the-kingsroad", summary: "The realm's great north-south road, from King's Landing up to the Wall.", description: "The realm's spine, running nearly two thousand miles from Storm's End through King's Landing and up to the Wall, becoming a causeway to cross the Neck and dwindling to two dirt tracks in places. Inns and villages crowd its middle stretch and thin out badly at either end, so travellers north of the Neck camp. It is the default setting for the story's transitions: the royal party's slow procession south, Arya and Yoren's recruits going north in a cage-cart, Brienne hunting a Stark girl, and every ambush in between.", also_called: ["the kingsroad","the road south","the road north"], adjacent: ["winterfell","moat-cailin","inn-at-the-crossroads","kings-landing","the-ruby-ford","the-tourney-grounds"] },
  { id: "the-eyrie", name: "The Eyrie", region: "The Vale", background: "the-eyrie", summary: "House Arryn's mountaintop castle above the Vale, the sheer-drop Moon Door for traitors.", description: "Seven slim white towers on a shoulder of the Giant's Lance, several thousand feet above the valley, reached only by mule and three small waycastles up a carved stair; it is the smallest of the great castles and reckoned impregnable, and it has no stables, smithy or kennels because nothing large can get up. Its High Hall is blue-veined white marble, and between two pillars stands the Moon Door, a weirwood hatch that opens onto six hundred feet of air. Lysa Arryn rules here in shrill paranoia with her sickly son Robert, Tyrion demands trial by combat rather than fly, and Littlefinger eventually sends Lysa out the door himself.", also_called: [], adjacent: ["gates-of-the-moon","bloody-gate"] },
  { id: "bloody-gate", name: "The Bloody Gate", region: "The Vale", background: "bloody-gate", summary: "Twin watchtowers guarding the high road into the Vale, never taken by force.", description: "Twin watchtowers built into the stone of the Mountains of the Moon, joined by an arched grey bridge over the high road where it narrows so that only four riders can pass abreast, with arrow slits covering every yard of it. A dozen armies have smashed themselves to bits against it in the Age of Heroes and Halleck Hoare failed three separate times. Its commander, the Knight of the Gate, challenges every traveller with the same ritual line: 'Who would pass the Bloody Gate?'", also_called: [], adjacent: ["gates-of-the-moon","the-eyrie","inn-at-the-crossroads"] },
  { id: "gates-of-the-moon", name: "The Gates of the Moon", region: "The Vale", background: "gates-of-the-moon", summary: "The Arryns' foothill castle below the Eyrie, their livable winter seat.", description: "The square-towered castle at the foot of the Giant's Lance, the Arryns' original seat and their winter refuge when the Eyrie becomes unliveable, held by Lord Nestor Royce as High Steward and Keeper. Mules are stabled here for the climb, torches flicker on the ramparts, and from the Eyrie above its keeps look like children's toys. This is where Littlefinger and 'Alayne Stone' overwinter, where Lord Nestor is bought with a hereditary title, and where the tourney of the Winged Knights is held.", also_called: [], adjacent: ["the-eyrie","bloody-gate"] },
  { id: "pyke", name: "Pyke", region: "Iron Islands", background: "pyke", summary: "House Greyjoy's storm-eaten seat on the Iron Islands, keeps linked by rope bridges.", description: "The Greyjoy seat, once built on a headland cliff that the sea has since eaten away, so that the Great Keep, the Kitchen Keep and the Bloody Keep now stand on separate islets and stacks joined by swaying rope-and-timber bridges over the surf, all grey-black stone gone green with lichen. There is no safe anchorage, only Lordsport nearby; the Great Hall is long and smoky and holds the Seastone Chair. Balon Greyjoy rejects his son Theon here as a green-land creature, and after Balon falls from a bridge the ironborn choose a new king by kingsmoot (on Old Wyk in the books; the show stages it at Pyke).", also_called: [], adjacent: ["lannisport","deepwood-motte","bear-island"] },
  { id: "casterly-rock", name: "Casterly Rock", region: "Westerlands", background: "casterly-rock", summary: "House Lannister's stronghold, a whole mountain hollowed into halls above the sea.", description: "Not a castle on a hill but a hill hollowed into a castle: a colossal stone mass six miles long and some 2,100 feet high above the Sunset Sea, said to look like a lion in repose, with every hall, barracks, dungeon, sept and goldmine carved inside it and only a rookery on the peak. The Lion's Mouth, a two-hundred-foot natural cavern, is the main gate; sea gates below let galleys sail in under the stone. Tywin Lannister's power radiates from here, Tyrion once ran its drains and cisterns, and in the show the Unsullied take it easily only because Jaime traded it away to sack Highgarden.", also_called: [], adjacent: ["lannisport","riverrun","highgarden"] },
  { id: "lannisport", name: "Lannisport", region: "Westerlands", background: "lannisport", summary: "The Westerlands' great port city just south of Casterly Rock, rich and often raided.", description: "A walled port city less than a mile south of Casterly Rock where the river road, the gold road and the ocean road meet, the largest settlement of the westerlands and one of the realm's great harbours, smaller than King's Landing or Oldtown but bigger than White Harbor. It is famous for goldsmiths, spiced honey wine, a well-drilled City Watch and expensive brothels. Being rich and close to the Iron Islands, it has been burned at least three times and raided two dozen more, most memorably when the Iron Fleet torched the Lannister ships at anchor to open the Greyjoy Rebellion.", also_called: [], adjacent: ["casterly-rock","riverrun","highgarden","pyke"] },
  { id: "kings-landing", name: "King's Landing", region: "Crownlands", background: "kings-landing", summary: "Westeros's sprawling capital on three hills at the Blackwater's mouth, seat of the crown.", description: "The capital and most populous city of Westeros, sprawling over three hills at the mouth of the Blackwater Rush behind tall walls patrolled by the gold cloaks, its stink carrying for miles beyond them. It is a warren of manses, winesinks, brothels, shanties and hundreds of quays, with the Red Keep on Aegon's High Hill, the Great Sept on Visenya's, and the broken Dragonpit dome on Rhaenys's. Everything political happens here, and so does everything ugly: Ned's arrest, the bread riot that tears a High Septon apart, and the burning of the city by dragonfire at the end.", also_called: ["the capital","the city"], adjacent: ["red-keep-throne-room","small-council-chamber","street-of-steel","black-cells","flea-bottom","great-sept-of-baelor","the-tourney-grounds","the-kingsroad"] },
  { id: "red-keep-throne-room", name: "The Red Keep (Throne Room)", region: "Crownlands", background: "red-keep-throne-room", summary: "The Red Keep's great hall, where the barbed Iron Throne sits atop iron steps.", description: "The Great Hall of the pale-red seven-towered castle on Aegon's High Hill, where the Iron Throne stands on a high platform reached by steep iron steps, an asymmetric monstrosity of a thousand twisted swords surrendered by Aegon's enemies, cold and hard and full of jagged edges that cut careless kings. Below the serpentine steps are Maegor's Holdfast, the small council chamber and the black cells; above them the Tower of the Hand, the godswood and the royal sept. Here Joffrey holds court, Ned is condemned, Tyrion is tried for regicide, and the Mad King died at his own Kingsguard's hand.", also_called: ["the Red Keep","the throne room","the Iron Throne"], adjacent: ["kings-landing","small-council-chamber","black-cells","flea-bottom","great-sept-of-baelor","blackwater-bay"], within: "kings-landing" },
  { id: "great-sept-of-baelor", name: "The Great Sept of Baelor", region: "Crownlands", background: "great-sept-of-baelor", summary: "King's Landing's marble domed sept, seat of the Faith and its High Septon.", description: "The seat of the High Septon and the centre of the Faith of the Seven, a great marble dome and seven slender crystal towers atop Visenya's Hill, surrounded by white marble plaza, gardens that hold hundreds, and a serene statue of Baelor the Blessed. Royal weddings, funerals and the Faith's ceremonies happen here. Ned Stark is beheaded on its steps before a screaming crowd, Joffrey and Margaery wed here, Cersei begins her naked walk of atonement from its doors, and in the show Cersei and Qyburn blow the whole building apart with wildfire, killing the Faith, the Tyrells and her own son's will to live.", also_called: ["the Great Sept","Baelor's Sept"], adjacent: ["kings-landing","red-keep-throne-room","street-of-steel","flea-bottom"], within: "kings-landing" },
  { id: "flea-bottom", name: "Flea Bottom", region: "Crownlands", background: "flea-bottom", summary: "King's Landing's poorest, most lawless slum, reeking alleys down Rhaenys's Hill.", description: "The poorest, foulest and most lawless slum of King's Landing, a maze of unpaved alleys running down the east side of Rhaenys's Hill where the buildings lean until they almost touch, thick with the reek of pigsties, tanneries and stables. Its pot-shops sell a 'bowl o' brown' with meat of unexamined origin; its gambling dens and rat pits absorb the rest. Gendry is apprenticed out of here, Arya hides in its alleys after her father's death, and the mob that forms here is the city's real government whenever grain runs short.", also_called: [], adjacent: ["kings-landing","street-of-steel","great-sept-of-baelor","dragonpit","blackwater-bay"], within: "kings-landing" },
  { id: "dragonpit", name: "The Dragonpit", region: "Crownlands", background: "dragonpit", summary: "Ruined domed arena on Rhaenys's Hill that once stabled the Targaryen dragons.", description: "A vast domed structure on Rhaenys's Hill that once stabled the Targaryen dragons, its main bronze gate wide enough for thirty knights abreast and its benches seating eighty thousand, with forty iron-doored undervaults burrowed into the hillside. Confinement here is blamed for the dragons shrinking generation by generation, and the whole thing was wrecked in the Storming of the Dragonpit during the Dance of the Dragons; it has stood a blackened ruin for a century and a half. In the show it hosts the Dragonpit Summit, where a captured wight is dumped out of a crate in front of Cersei, and later the council that elects Bran.", also_called: [], adjacent: ["kings-landing","flea-bottom","red-keep-throne-room"], within: "kings-landing" },
  { id: "small-council-chamber", name: "The Small Council Chamber", region: "Crownlands", background: "small-council-chamber", summary: "The Red Keep's council room where the realm's business is settled around one table.", description: "A modest room below the throne room in Maegor's Holdfast, with a long table, a window over the city and chairs enough for the Hand, the Grand Maester and the masters of coin, ships, laws and whisperers. Everything that governs the Seven Kingdoms is settled here in half an hour of courteous knives: the Crown's six million in debt to the Lannisters and the Iron Bank, the murder of a girl across the narrow sea, who is named Hand and who is quietly unnamed. Ned reads the ledgers here and discovers the realm is bankrupt; Littlefinger and Varys trade barbs across the table for the pleasure of it; Tywin has the chairs dragged round so that he sits at the head with the light behind him; and Cersei fills the seats with Qyburn and her own creatures until nobody is left to say no.", also_called: ["the small council","the council chamber"], adjacent: ["kings-landing","red-keep-throne-room","black-cells"], within: "kings-landing" },
  { id: "street-of-steel", name: "The Street of Steel", region: "Crownlands", background: "street-of-steel", summary: "King's Landing's armourers' street climbing Visenya's Hill, ringing with hammers all day.", description: "The street where King's Landing's smiths work, climbing Visenya's Hill from the Mud Gate with the knife-grinders and cheap forges at the bottom and the master armourers in their gilded shopfronts at the top, the ring of hammers carrying three streets in every direction. Tobho Mott's house near the crest is faced in ebony and weirwood, and he is one of the few men in Westeros who can rework Valyrian steel, which is why Tywin Lannister sends him Ice to be melted down and beaten into two new swords. Gendry is apprenticed here and hammers out a bull's-head helm nobody will let him sell, and it is up this street that Ned Stark walks, tracing Jon Arryn's last errand, to meet his brother's bastard without ever knowing what he is looking at.", also_called: [], adjacent: ["kings-landing","flea-bottom","great-sept-of-baelor"], within: "kings-landing" },
  { id: "black-cells", name: "The Black Cells", region: "Crownlands", background: "black-cells", summary: "Lightless dungeons under the Red Keep, where the Crown keeps prisoners it forgets.", description: "The lowest of the Red Keep's four levels of dungeon, cut into the rock beneath Aegon's High Hill: windowless stone cells with heavy wooden doors, a slot for a bowl of food, no light of any kind and nothing at all to mark one day off from the next. A man put here is left alone in the dark until somebody wants him. Ned Stark lies in one with a shattered leg after Littlefinger's betrayal, drinking from a pitcher he cannot see, until Varys comes by candlelight to explain that his daughters' lives are the price of a public lie — and gets it, on the steps of Baelor's Sept. Grand Maester Pycelle is thrown down here by Tyrion with his beard hacked off, and the undergaoler Rugen comes and goes as he pleases because Rugen is Varys wearing another face.", also_called: ["the dungeons"], adjacent: ["red-keep-throne-room","small-council-chamber","kings-landing"], within: "kings-landing" },
  { id: "blackwater-bay", name: "Blackwater Bay", region: "Crownlands", background: "blackwater-bay", summary: "The calm inlet before King's Landing, site of Stannis's wildfire naval battle.", description: "A broad, comparatively calm inlet of the narrow sea held between Crackclaw Point and Massey's Hook, entered through the Gullet past Dragonstone and Driftmark, with King's Landing at the head of it where the Blackwater Rush pours in. The royal fleet patrols it, Duskendale serves as its second port, and the treacherous spears of the merling king lurk in its currents. It is the setting of the largest battle of the War of the Five Kings, when Tyrion's chain rises behind Stannis's fleet and Bronn lights a single flaming arrow to touch off the wildfire.", also_called: [], adjacent: ["kings-landing","the-tourney-grounds","dragonstone","red-keep-throne-room","storms-end"] },
  { id: "the-tourney-grounds", name: "The Tourney Grounds", region: "Crownlands", background: "the-tourney-grounds", summary: "Lists, pavilions and stands outside King's Landing where knights joust before the court.", description: "The meadow outside the city walls given over to a tourney: a railed tilt down the middle, a hundred silk pavilions with each knight's shield hung before his door, raised stands for the court and standing room for everyone else, and a fair of vendors, whores, horse traders and hedge knights camped in the fields around. The Hand's tourney draws forty thousand and costs the Crown ninety thousand golden dragons it does not have, which is the point of it. Ser Hugh of the Vale dies on Gregor Clegane's lance with a splinter through his throat, Loras Tyrell unhorses the Mountain by riding a mare in heat and the Hound saves his life in front of the king, and Ser Dontos turns up too drunk to sit a horse and is made a fool instead of drowned in a butt of wine.", also_called: ["the lists","the tourney field"], adjacent: ["kings-landing","the-kingsroad","blackwater-bay"] },
  { id: "dragonstone", name: "Dragonstone", region: "Crownlands", background: "dragonstone", summary: "House Targaryen's volcanic island seat under a smoking mountain in Blackwater Bay.", description: "A bleak volcanic island at the mouth of Blackwater Bay under the smoking Dragonmont, and the ancestral Westerosi seat of House Targaryen, fortified by the Valyrian Freehold long before the Conquest. Its castle is shaped by sorcery into gargoyles, dragons and stone beasts, dark and old and thinly garrisoned, commanding only a few small island houses. Stannis Baratheon broods here while Melisandre burns the Seven on the beach and births a shadow in its caves, and Daenerys later lands here to claim the empty chair that was hers by birth.", also_called: [], adjacent: ["blackwater-bay","kings-landing","storms-end","pentos"] },
  { id: "storms-end", name: "Storm's End", region: "Stormlands", background: "storms-end", summary: "House Baratheon's storm-proof drum-tower castle above Shipbreaker Bay, never taken by siege.", description: "The Baratheon seat on Durran's Point above Shipbreaker Bay, one enormous drum tower inside a smooth curving curtain wall a hundred feet high and up to eighty feet thick, built so that the wind can find no purchase and reputedly warded by spells woven into the stone. Legend says Durran Godsgrief raised six castles that the storm gods smashed before the seventh held. Stannis held it through a year-long siege eating rats until Davos smuggled onions in; Renly is killed by a shadow in his own tent outside it, and its castellan Cortnay Penrose dies the same way.", also_called: [], adjacent: ["the-kingsroad","blackwater-bay","bitterbridge","highgarden","dragonstone"] },
  { id: "highgarden", name: "Highgarden", region: "The Reach", background: "highgarden", summary: "House Tyrell's lush castle on the Mander, roses and a famous briar maze.", description: "The Tyrell seat on a broad green hill above the Mander where the ocean road meets the roseroad, three rising rings of white curtain wall with a famous briar labyrinth between the outer two, ivy and climbing roses over everything, and three weirwoods in its godswood called the Three Singers. It is the acknowledged heart of chivalry, full of pipers, harpers, pleasure boats and fields of golden roses. Olenna Tyrell runs the family from here with total contempt for everyone; in the show Jaime sacks it and gives her poisoned wine, and she uses her last breath to tell him she killed Joffrey.", also_called: [], adjacent: ["oldtown-and-the-citadel","horn-hill","bitterbridge","lannisport","kings-landing"] },
  { id: "oldtown-and-the-citadel", name: "Oldtown and the Citadel", region: "The Reach", background: "oldtown-and-the-citadel", summary: "Westeros's oldest city and the Citadel, seat of the maesters' order.", description: "The oldest, richest and second-largest city of Westeros, all cobbled streets and stone bridges at the mouth of the Honeywine, crowned by the Hightower's beacon on Battle Isle and holding the Starry Sept, once seat of the Faith. Upriver stands the Citadel, gates flanked by two green sphinxes, where archmaesters wearing their disciplines as chain links teach, copy books, and quietly distrust magic. Samwell Tarly comes here to forge his chain and read about dragonglass, and finds the order guarding more secrets than it shares.", also_called: ["Oldtown","the Citadel"], adjacent: ["highgarden","horn-hill","braavos"] },
  { id: "horn-hill", name: "Horn Hill", region: "The Reach", background: "horn-hill", summary: "House Tarly's wooded marcher seat south of Highgarden, home of the sword Heartsbane.", description: "The Tarly seat in thickly wooded foothills of the Red Mountains south of Highgarden, a marcher lord's castle with walls Sam himself calls less formidable than Oldtown's, a pond below and woods around it teeming with game. Lord Randyll Tarly is the finest soldier in the Reach and a monster to his own son, having given Sam a choice between the black and a hunting accident. It is where the ancestral Valyrian steel greatsword Heartsbane hangs, and where Sam returns with Gilly and a baby to a very cold family dinner before stealing the sword and leaving.", also_called: [], adjacent: ["highgarden","oldtown-and-the-citadel","sunspear"] },
  { id: "bitterbridge", name: "Bitterbridge", region: "The Reach", background: "bitterbridge", summary: "Reach crossing of the Mander on the roseroad, where hosts muster and change sides.", description: "A market town and a long stone bridge where the roseroad crosses the Mander, held by House Caswell from the castle above it, and the place any army moving between Highgarden and King's Landing has to pass through. Renly Baratheon musters a hundred thousand men in the fields here and holds a tourney of picked knights for his own amusement while he waits; it is in that melee that Brienne of Tarth beats Loras Tyrell with a morningstar and asks for her place in the Rainbow Guard. When Renly is murdered at Storm's End the camp comes apart in a morning — Catelyn and Brienne ride out of it as fugitives, most of the host bends the knee to Stannis, and Littlefinger buys the rest for Joffrey with the promise of a Tyrell marriage.", also_called: [], adjacent: ["highgarden","storms-end","kings-landing"] },
  { id: "sunspear", name: "Sunspear", region: "Dorne", background: "sunspear", summary: "House Martell's walled desert capital of Dorne, concentric Winding Walls and a Spear Tower.", description: "The Martell seat and capital of Dorne on the Broken Arm, sea on three sides and the dusty shadow city on the fourth, protected by three concentric Winding Walls full of narrow alleys, hidden courts and noisy bazaars, with the Threefold Gate cutting straight through the maze to the Old Palace. Its landmarks are the squat old Sandship, the slender Spear Tower where noble prisoners are kept, and the domed Tower of the Sun where the Prince of Dorne sits on twin thrones. Doran Martell rules from a wheeled chair, gout-ridden and apparently passive, while his brother Oberyn and the Sand Snakes push for open vengeance on the Lannisters.", also_called: [], adjacent: ["water-gardens","horn-hill","storms-end"] },
  { id: "water-gardens", name: "The Water Gardens", region: "Dorne", background: "water-gardens", summary: "The Martells' pink marble pleasure palace of pools near Sunspear, where children foster.", description: "A pink marble palace of pools, fountains and terraces shaded by blood orange trees, on a beach three leagues west of Sunspear along the coastal road, built as a private Martell retreat. Children of every station in Dorne are sent here to foster and play together in the water, which is the point of it; the days are hot, the nights cool, and the salt breeze never stops. Doran holds court here in seeming idleness while quietly moving a plan twenty years in the making, and in the show it is where Jaime's clumsy attempt to smuggle Myrcella out collapses into a scuffle with the Sand Snakes.", also_called: [], adjacent: ["sunspear","horn-hill"] },
  { id: "braavos", name: "Braavos", region: "Essos", background: "braavos", summary: "The richest Free City, built on a fogbound lagoon, guarded by the bronze Titan.", description: "The richest and most powerful of the Nine Free Cities, founded by escaped slaves and still fiercely abolitionist, sprawled across a hundred islands in a fog-bound lagoon where the narrow sea meets the Shivering Sea, moved about by canal and bridge rather than road. Ships enter beneath the Titan, a granite-and-bronze colossus that roars at dawn and dusk and serves as fortress and lighthouse; inside are the Arsenal, the Moon Pool, the Iron Bank that no king dares default on, and duelling bravos in the streets at night. Arya Stark arrives here with a coin and the words valar morghulis; Davos comes to beg the Bank for Stannis's war.", also_called: [], adjacent: ["house-of-black-and-white","purple-harbor","pentos","eastwatch-by-the-sea","white-harbor"] },
  { id: "house-of-black-and-white", name: "The House of Black and White", region: "Essos", background: "house-of-black-and-white", summary: "Windowless Braavosi temple of the Many-Faced God, home of the Faceless Men.", description: "A windowless temple of dark grey stone on a knoll above a Braavosi canal, its twelve-foot doors half weirwood and half ebony, sheltering a dim hall of thirty gods around a black pool of gently poisoned water lit by red candles. It is the temple of the Many-Faced God and the headquarters of the Faceless Men, who give the gift of death for a price, and beneath it lie sleeping cells, bone-lined passages and a vault of harvested faces. Arya washes corpses, is blinded, learns to lie, becomes 'no one' and then refuses to stop being Arya Stark.", also_called: ["the temple of the Many-Faced God"], adjacent: ["braavos","purple-harbor","pentos"], within: "braavos" },
  { id: "purple-harbor", name: "The Purple Harbor", region: "Essos", background: "purple-harbor", summary: "Braavos's inner harbour for Braavosi ships alone, ringed by the city's seats of power.", description: "The inner harbour of Braavos, closed to every hull that is not Braavosi, its green water crowded with pleasure barges and serpent boats and its quays running beneath the Sealord's Palace, the Palace of Truth and the squat towered vault of the Iron Bank. This is where the city's money and its government touch the sea: the Sealord is rowed out from these steps, and a debt written a street away has toppled kings, since the Bank keeps no armies and does not need any. Syrio Forel was first sword to the Sealord before he went west to teach a Stark girl to dance; Arya works these quays as Cat of the Canals with a barrow of cockles and mussels, learning faces, names and how a city talks; and in the show Davos Seaworth lands here to beg a loan for a king nobody believes in.", also_called: [], adjacent: ["braavos","house-of-black-and-white"], within: "braavos" },
  { id: "pentos", name: "Pentos", region: "Essos", background: "pentos", summary: "Free City nearest Westeros, walled merchant port ruled by a ceremonial prince.", description: "The Free City closest to Westeros, a rich port of square brick towers and tiled roofs behind massive walls, ruled in practice by a council of merchant magisters and in theory by a prince who deflowers two maidens each new year and gets his throat cut if the harvest fails. Slavery is banned by Braavosi treaty and everywhere in fact, under the name of free bond servants. This is where the story leaves Westeros first: Illyrio Mopatis's walled manse, Viserys selling his sister, Daenerys's Dothraki wedding on the grass, and three petrified dragon eggs given as a gift.", also_called: [], adjacent: ["braavos","volantis","dothraki-sea","dragonstone"] },
  { id: "volantis", name: "Volantis", region: "Essos", background: "volantis", summary: "Oldest Free City, straddling the Rhoyne's mouth behind ancient Black Walls, five slaves per freeman.", description: "The oldest and proudest of the Free Cities, the First Daughter of Valyria, straddling the mouth of the Rhoyne in wet heat that can drown a man in his own sweat, its two halves joined by the Long Bridge and its ancient eastern core sealed behind the Black Walls, two hundred feet of fused dragonstone wide enough to race chariots along the top. Five slaves for every free man, all of them tattooed on the face by trade, and the largest temple of R'hllor in the world with a preaching priest and a slave-soldier order. Tyrion and Jorah pass through on their way east and Tyrion gets himself abducted here.", also_called: [], adjacent: ["pentos","meereen","valyria-and-the-smoking-sea","slavers-bay"] },
  { id: "meereen", name: "Meereen", region: "Essos", background: "meereen", summary: "Largest Slaver's Bay city, stepped brick pyramids topped by a bronze harpy.", description: "The largest and strongest of the three slaver cities, built of many-coloured brick at the mouth of the Skahazadhan with walls studded with bronze harpy heads that spit boiling oil, and stepped pyramids rising above it, the Great Pyramid tallest at eight hundred feet and thirty-three levels with a bronze harpy on its apex. Daenerys takes it, crucifies a hundred and sixty-three Great Masters, and then discovers that ruling a city she has broken is much harder than breaking it. The Sons of the Harpy murder her freedmen in the alleys by night, and in Daznak's fighting pit her open-air court ends with Drogon descending into the sand.", also_called: [], adjacent: ["great-pyramid","daznaks-pit","yunkai","slavers-bay","dothraki-sea","astapor"] },
  { id: "great-pyramid", name: "The Great Pyramid", region: "Essos", background: "great-pyramid", summary: "Meereen's eight-hundred-foot brick pyramid, the queen's seat above the whole city.", description: "The tallest of Meereen's stepped brick pyramids, eight hundred feet from base to the bronze harpy on its crown, and a city inside a building: slave barracks and stables at the bottom, storerooms and halls through the middle, and at the top an open terrace of persimmon trees, fountains and a view across every roof in Meereen to the sea. Daenerys takes it as her seat, holds audience in a hall of purple marble on a plain bench rather than a throne, and hears petitioners from dawn until her back gives out. She chains Viserion and Rhaegal in a vault beneath it after Drogon burns a child in the fields; Quentyn Martell, the Green Grace and Hizdahr zo Loraq all bring her their terms up these stairs; and it is from this terrace that she rules a city that will not be ruled.", also_called: ["the pyramid"], adjacent: ["meereen","daznaks-pit"], within: "meereen" },
  { id: "daznaks-pit", name: "Daznak's Pit", region: "Essos", background: "daznaks-pit", summary: "Meereen's greatest fighting pit: sand, tiered benches and sixteen thousand screaming for blood.", description: "The largest of Meereen's fighting pits, a brick oval of tiered benches seating sixteen thousand around a floor of sand that is raked smooth between bouts, with the queen's box shaded above the gates the fighters come out of. Daenerys closes the pits when she takes the city and reopens them as the price of Hizdahr zo Loraq's peace, and sits through dwarfs jousting on pigs, a bear against three men and Strong Belwas cutting open a Spotted Cat, hating every moment of the thing she agreed to. The smell of blood on the sand brings Drogon down out of the sky; the Sons of the Harpy rise in the seats and the crowd turns, and Daenerys climbs onto the dragon's back with a whip and flies out of Meereen, leaving her city, her court and her war on the ground behind her.", also_called: ["the fighting pits"], adjacent: ["meereen","great-pyramid"], within: "meereen" },
  { id: "astapor", name: "Astapor", region: "Essos", background: "astapor", summary: "The Red City of Slaver's Bay, birthplace of the eunuch Unsullied soldiers.", description: "The Red City, southernmost of the slaver cities, all crumbling red brick and stepped pyramids terraced with vines and flowers, its harpy sigil clutching a chain with open manacles. Its entire reputation rests on the Unsullied, eunuch slave soldiers broken in childhood, trained to absolute obedience and made to kill a newborn as the last step; the Good Masters sell them by the thousand and treat buyers with lazy contempt. Daenerys trades a dragon for eight thousand of them, has the chains handed over, and then says one word, 'Dracarys'.", also_called: [], adjacent: ["yunkai","meereen","slavers-bay"] },
  { id: "yunkai", name: "Yunkai", region: "Essos", background: "yunkai", summary: "The Yellow City of Slaver's Bay, crumbling brick walls, trades in bed slaves.", description: "The Yellow City, of yellow brick with crumbling walls and towers and a great harpy mounted above its gates, a hundred leagues north of Astapor along the old Ghiscari coastal road. Its Wise Masters trade in bed slaves trained in the seven sighs, which makes it disreputable even by Slaver's Bay standards, and its highborn oil their hair into towers and wear fringed tokars. Daenerys takes it not by siege but by infiltration in the night, and the freed slaves come out of the gates chanting 'Mhysa' at her.", also_called: [], adjacent: ["astapor","meereen","slavers-bay"] },
  { id: "qarth", name: "Qarth", region: "Essos", background: "qarth", summary: "Walled desert city on the Jade Gates, ruled by the Pureborn and Thirteen.", description: "The self-styled greatest city that ever was or will be, sitting on the Jade Gates between the Summer Sea and the Jade Sea, behind three walls of thirty, forty and fifty feet carved respectively with animals, war and lovemaking, with the red waste at its back so the Dothraki never touch it. It is fabulously rich and fabulously supercilious, run by the Pureborn, the Thirteen and the Ancient Guild of Spicers, and it will happily bar the gates and let you die outside among the bones. Daenerys is courted by Xaro Xhoan Daxos and walks into the warlocks' House of the Undying, where the prophecies are worth more than the hospitality.", also_called: [], adjacent: ["slavers-bay","meereen","dothraki-sea"] },
  { id: "vaes-dothrak", name: "Vaes Dothrak", region: "Essos", background: "vaes-dothrak", summary: "The Dothraki's only city, wall-less, ruled by the crone widows called dosh khaleen.", description: "The only Dothraki city, wall-less and half empty, lying under the Mother of Mountains beside the lake called the Womb of the World, its broad streets paved in grass and mud and lined with plundered monuments dragged home from a hundred conquered peoples along the godsway between the Horse Gate and the mountain. It is ruled by the dosh khaleen, the widowed crones of dead khals, and it is death to draw a blade or shed free blood inside it. Daenerys eats a stallion's raw heart before the crones here, and Viserys gets the golden crown he asked for.", also_called: [], adjacent: ["western-market","dothraki-sea","meereen","pentos"] },
  { id: "western-market", name: "The Western Market", region: "Essos", background: "western-market", summary: "Vaes Dothrak's market for Westerosi goods, where traders barter under the city's peace.", description: "One of the great markets of Vaes Dothrak, given over to the goods of the Sunset Lands, where merchants out of Pentos, Myr and Qohor lay out wine, silver, silk, saddles and books under awnings and the Dothraki take what they please as gifts rather than buy it. No blade may be drawn and no blood spilled inside the sacred city, so this is the one place in the world where a Westerosi can walk through a khalasar unarmed and expect to walk out again. Daenerys comes here to shop and to hear her own tongue spoken, and a wine-seller sent by Robert Baratheon offers her a cask of sweet Arbor red to drink for the sake of her unborn son — Ser Jorah, who has read the same letter, makes the man drink first. What Drogo swears in answer turns the khalasar west, toward the poison water and the Iron Throne.", also_called: [], adjacent: ["vaes-dothrak","dothraki-sea"], within: "vaes-dothrak" },
  { id: "dothraki-sea", name: "The Dothraki Sea", region: "Essos", background: "dothraki-sea", summary: "Vast grass ocean across central Essos, home to the horse-riding Dothraki khalasars.", description: "A vast inland ocean of grass across central Essos, bounded by the Forest of Qohor to the west and the Bone Mountains to the east, where more than a hundred kinds of grass grow taller than a man's head and roll in waves under the wind. The Dothraki khalasars ride it in their thousands, following the herds and raiding everything sedentary; a white lion called the hrakkar hunts here. It is pure travel country, endless and exposed, where Daenerys learns to ride with Drogo and where, much later, Drogon sets her down alone in the grass in front of a horde.", also_called: [], adjacent: ["vaes-dothrak","western-market","meereen","pentos","qarth"] },
  { id: "valyria-and-the-smoking-sea", name: "Valyria and the Smoking Sea", region: "Essos", background: "valyria-and-the-smoking-sea", summary: "The Doom-shattered Valyrian homeland, a cursed archipelago in a smoking, demon-haunted sea.", description: "The shattered heart of the Valyrian Freehold, whose dragonlords practised blood magic and twisted flesh until, four hundred years ago, the Fourteen Flames burst, dragonglass rained from red clouds, the peninsula cracked, and the sea rushed in. What remains is a broken archipelago around a still-boiling, smoking, demon-haunted sea that sailors will not cross, with the drowned ruins of the old city at its centre and Valyrian steel and stranger treasures somewhere under them. In the show Tyrion and Jorah sail through its ruins and are attacked by greyscale-ridden stone men (in the books that ambush happens at Chroyane on the Rhoyne instead).", also_called: ["Valyria","the Smoking Sea"], adjacent: ["volantis","slavers-bay","meereen"] },
  { id: "slavers-bay", name: "Slaver's Bay", region: "Essos", background: "slavers-bay", summary: "The hot coastal region holding Astapor, Yunkai and Meereen, built on the slave trade.", description: "The hot, brick-built coastal region raised from the ashes of the Old Empire of Ghis, holding Astapor, Yunkai and Meereen and feeding on the global slave trade, its waters running out through the Gulf of Grief past the Isle of Cedars. The old Ghiscari coastal road links the three cities across a hundred and fifty leagues of dust, and slave galleys, Volantene traders and Qartheen merchantmen work the bay between them. It functions as the connective tissue of the eastern story: shipboard councils, coast marches, blockades, and the slaver fleets that come back to retake what Daenerys freed.", also_called: [], adjacent: ["astapor","yunkai","meereen","volantis"] },
] as const satisfies ReadonlyArray<LocationSeed>;

export type LocationId = (typeof locations)[number]["id"];
